def retry_delays(max_retries, base_ms=100, cap_ms=5000):
    if max_retries < 0:
        raise ValueError("max_retries must be non-negative")
    if base_ms <= 0:
        raise ValueError("base_ms must be positive")
    if cap_ms <= 0:
        raise ValueError("cap_ms must be positive")
    return [min(base_ms * (2 ** attempt), cap_ms) for attempt in range(max_retries)]

def redact_secrets(value):
    """Recursively copy dicts/lists, replacing secret-bearing values with "***".

    A value is replaced when its dictionary key contains (case-insensitively)
    "password", "token", "secret", or "api_key". The input is never mutated.
    """
    if isinstance(value, dict):
        result = {}
        for key, val in value.items():
            if _is_secret_key(key):
                result[key] = "***"
            else:
                result[key] = redact_secrets(val)
        return result
    if isinstance(value, list):
        return [redact_secrets(item) for item in value]
    return value


_SECRET_SUBSTRINGS = ("password", "token", "secret", "api_key")


def _is_secret_key(key):
    if not isinstance(key, str):
        return False
    lowered = key.lower()
    return any(substring in lowered for substring in _SECRET_SUBSTRINGS)
